/**
 * /pages/Medicine.jsx
 * ---------------------------------------------------------------------------
 * Demo gọi API qua model/api.js -> model/http.js (axios).
 * Có chế độ MOCK để chạy được ngay khi chưa có server.
 */

import React, { useEffect, useState } from 'react'
import {
  Table, Button, Space, Input, Card, Tag, message, Upload, Switch, Typography,
} from 'antd'
import {
  ReloadOutlined, PlusOutlined, UploadOutlined, DownloadOutlined, SearchOutlined,
} from '@ant-design/icons'

import PageHeader from '@/components/PageHeader'
import api from '@/model/api'
import { useAppDispatch, useAppSelector, mutations } from '@/store'
import { getters } from '@/store/getters'
import { useRouter } from '@/router'
import { useI18n } from '@/lang'
import { formatCurrency, formatDate, cleanParams } from '@/utils'

const { Text } = Typography

// ---- dữ liệu mock (dùng khi chưa có API server) ----------------------------
const MOCK_DATA = [
  { id: 1, code: 'MED001', name: 'Paracetamol 500mg', unit: 'Hộp', price: 25000, expiry: '2026-12-31', status: 1 },
  { id: 2, code: 'MED002', name: 'Amoxicillin 250mg', unit: 'Hộp', price: 68000, expiry: '2026-08-15', status: 1 },
  { id: 3, code: 'MED003', name: 'Vitamin C 1000mg', unit: 'Lọ', price: 120000, expiry: '2027-03-20', status: 0 },
  { id: 4, code: 'MED004', name: 'Ibuprofen 400mg', unit: 'Hộp', price: 45000, expiry: '2026-11-01', status: 1 },
]

const Medicine = () => {
  const router = useRouter()
  const dispatch = useAppDispatch()
  const { t } = useI18n()
  const medicineList = useAppSelector(getters.medicineList)
  const loading = useAppSelector(getters.loading)

  const [keyword, setKeyword] = useState('')
  const [useMock, setUseMock] = useState(true)

  /** Gọi API lấy danh sách */
  const fetchList = async () => {
    dispatch(mutations.setLoading(true))
    try {
      if (useMock) {
        // giả lập độ trễ mạng
        await new Promise((r) => setTimeout(r, 400))
        dispatch(mutations.setMedicineList(MOCK_DATA))
      } else {
        const res = await api.medicineApi.list(
          cleanParams({ keyword, page: 1, size: 20 }),
        )
        dispatch(mutations.setMedicineList(res?.data || res || []))
      }
      message.success(t('Tải dữ liệu thành công'))
    } catch (err) {
      // lỗi đã được http.js hiển thị message
      console.error(err)
    } finally {
      dispatch(mutations.setLoading(false))
    }
  }

  useEffect(() => {
    fetchList()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [useMock])

  /** Upload file excel -> postfile */
  const handleUpload = async ({ file, onSuccess, onError }) => {
    try {
      if (useMock) {
        await new Promise((r) => setTimeout(r, 600))
        message.success(`Đã upload (mock): ${file.name}`)
      } else {
        await api.medicineApi.importExcel(file, (percent) =>
          console.log('upload', percent),
        )
        message.success(t('Import thành công'))
      }
      onSuccess?.({})
      fetchList()
    } catch (e) {
      onError?.(e)
    }
  }

  /** Export excel -> getfile */
  const handleExport = async () => {
    try {
      if (useMock) {
        const csv = ['code,name,unit,price']
          .concat(MOCK_DATA.map((m) => `${m.code},${m.name},${m.unit},${m.price}`))
          .join('\n')
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = 'medicine.csv'
        a.click()
        URL.revokeObjectURL(url)
      } else {
        await api.medicineApi.exportExcel({ keyword }, 'medicine.xlsx')
      }
      message.success(t('Export thành công'))
    } catch (e) {
      console.error(e)
    }
  }

  const columns = [
    { title: t('STT'), width: 60, render: (_, __, i) => i + 1 },
    { title: t('Mã'), dataIndex: 'code', width: 110 },
    {
      title: t('Tên thuốc'),
      dataIndex: 'name',
      render: (v, row) => (
        <a onClick={() => router.push({ name: 'medicine-detail', params: { id: row.id } })}>
          {v}
        </a>
      ),
    },
    { title: t('Đơn vị'), dataIndex: 'unit', width: 90 },
    {
      title: t('Đơn giá'),
      dataIndex: 'price',
      width: 130,
      align: 'right',
      render: (v) => formatCurrency(v),
    },
    {
      title: t('Hạn dùng'),
      dataIndex: 'expiry',
      width: 120,
      render: (v) => formatDate(v),
    },
    {
      title: t('Trạng thái'),
      dataIndex: 'status',
      width: 120,
      render: (v) =>
        v === 1 ? (
          <Tag color="green">{t('Đang bán')}</Tag>
        ) : (
          <Tag color="red">{t('Ngừng bán')}</Tag>
        ),
    },
    {
      title: t('Thao tác'),
      width: 110,
      render: (_, row) => (
        <Button
          type="link"
          size="small"
          onClick={() => router.push({ name: 'medicine-detail', params: { id: row.id } })}
        >
          {t('Chi tiết')}
        </Button>
      ),
    },
  ]

  return (
    <>
      <PageHeader
        title={t('Danh mục thuốc')}
        subtitle={t('Demo gọi API qua model/api.js → model/http.js (axios)')}
        extra={
          <Space>
            <Text type="secondary">{t('Dùng dữ liệu mock')}</Text>
            <Switch checked={useMock} onChange={setUseMock} />
          </Space>
        }
      />

      <Card size="small" className="mb-16">
        <Space wrap>
          <Input
            allowClear
            className="medicine-search"
            placeholder={t('Tìm theo tên / mã thuốc')}
            prefix={<SearchOutlined />}
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onPressEnter={fetchList}
          />
          <Button type="primary" icon={<SearchOutlined />} onClick={fetchList}>
            {t('Tìm kiếm')}
          </Button>
          <Button icon={<ReloadOutlined />} onClick={fetchList}>
            {t('Tải lại')}
          </Button>
          <Button type="primary" ghost icon={<PlusOutlined />}>
            {t('Thêm mới')}
          </Button>
          <Upload customRequest={handleUpload} showUploadList={false} accept=".xlsx,.xls,.csv">
            <Button icon={<UploadOutlined />}>{t('Import Excel')}</Button>
          </Upload>
          <Button icon={<DownloadOutlined />} onClick={handleExport}>
            {t('Export Excel')}
          </Button>
        </Space>
      </Card>

      <Table
        rowKey="id"
        size="small"
        loading={loading}
        columns={columns}
        dataSource={medicineList}
        pagination={{ pageSize: 10, showSizeChanger: true }}
        scroll={{ x: 900 }}
      />
    </>
  )
}

export default Medicine
