/**
 * /model/api.js
 * ---------------------------------------------------------------------------
 * Khai báo các ENDPOINT API của hệ thống.
 * Mỗi hàm ở đây chỉ gọi tới post / get / postfile / getfile trong http.js.
 *
 * Cách dùng:
 *   import api from '@/model/api'
 *   const res = await api.login({ username, password })
 */

import { post, get, postfile, getfile } from './http'

/* =========================================================================
 *  AUTH
 * ========================================================================= */
export const authApi = {
  login: (data) => post('/auth/login', data),
  logout: () => post('/auth/logout'),
  profile: () => get('/auth/profile'),
  changePassword: (data) => post('/auth/change-password', data),
}

/* =========================================================================
 *  MEDICINE  (ví dụ theo base path /medicine)
 * ========================================================================= */
export const medicineApi = {
  /** danh sách thuốc có phân trang + tìm kiếm */
  list: (params) => get('/medicine/list', params),

  /** chi tiết 1 thuốc */
  detail: (id) => get(`/medicine/detail/${id}`),

  /** thêm mới */
  create: (data) => post('/medicine/create', data),

  /** cập nhật */
  update: (data) => post('/medicine/update', data),

  /** xoá */
  remove: (id) => post('/medicine/delete', { id }),

  /** import excel */
  importExcel: (file, onProgress) => postfile('/medicine/import', { file }, onProgress),

  /** export excel */
  exportExcel: (params, fileName = 'medicine.xlsx') =>
    getfile('/medicine/export', params, fileName),
}

/* =========================================================================
 *  UPLOAD / FILE
 * ========================================================================= */
export const fileApi = {
  upload: (file, onProgress) => postfile('/file/upload', { file }, onProgress),
  download: (id, fileName) => getfile(`/file/download/${id}`, {}, fileName),
}

/* =========================================================================
 *  TODO (demo)
 * ========================================================================= */
export const todoApi = {
  list: (params) => get('/todo/list', params),
  create: (data) => post('/todo/create', data),
  update: (data) => post('/todo/update', data),
  remove: (id) => post('/todo/delete', { id }),
}

const api = { authApi, medicineApi, fileApi, todoApi }
export default api
